mapper.update:
        MERGE INTO T_CONSTRUCTION_VERSION_INFO a USING (


            SELECT id,
            	   #{item.embryoCode} EMBRYO_CODE,
            	   #{item.embryoVersion,jdbcType = VARCHAR} EMBRYO_VERSION,
            	   #{item.currentDate} current_date,




	         	   #{column.columnValue,jdbcType = VARCHAR} ${column.columnName}


	         	   TO_CHAR(${column.columnName}) ${column.columnName}




              FROM DUAL
              LEFT JOIN T_CONSTRUCTION_VERSION_INFO t
                ON EMBRYO_CODE = #{item.embryoCode}
               AND EMBRYO_VERSION = #{item.embryoVersion,jdbcType = VARCHAR}
			   AND T.DEL_FLAG = '0'

        ) b ON (a.EMBRYO_CODE = b.EMBRYO_CODE AND a.EMBRYO_VERSION = b.EMBRYO_VERSION AND a.DEL_FLAG = '0')
        WHEN MATCHED THEN
        UPDATE SET
            a.update_time = b.current_date,

            a.${column} = b.${column}

        WHEN NOT MATCHED THEN
        INSERT (a.id,a.create_time,a.update_time,a.EMBRYO_CODE, a.EMBRYO_VERSION,

            a.${column}

        ) values
        (get_sequence_nextval('SEQ_CONSTRUCTION_INFO'),b.current_date,b.current_date,b.EMBRYO_CODE, b.EMBRYO_VERSION,

            b.${column}

		)

mapper.select:
WITH BOM_TAB AS (SELECT * FROM T_BOM_INFO T WHERE T.CHILD_MATERIAL_NAME_CODE = 'EMBRYO' AND T.Child_Material_Version IS NOT NULL
AND NOT EXISTS (SELECT 1 FROM T_BOM_INFO TT WHERE TT.CHILD_MATERIAL_CODE = T.CHILD_MATERIAL_CODE AND TT.PARENT_MATERIAL_CODE = T.PARENT_MATERIAL_CODE AND TT.CHILD_MATERIAL_VERSION = T.CHILD_MATERIAL_VERSION AND TT.CHILD_MATERIAL_NAME_CODE = 'EMBRYO' AND ((SUBSTR(TT.SAP_VERSION, 0, 1) > SUBSTR(T.SAP_VERSION, 0, 1) OR SUBSTR(TT.SAP_VERSION, 0, 1) = SUBSTR(T.SAP_VERSION, 0, 1) AND TO_NUMBER(REGEXP_SUBSTR(SUBSTR(TT.SAP_VERSION, 2), '[0-9]+')) > TO_NUMBER(REGEXP_SUBSTR(SUBSTR(T.SAP_VERSION, 2), '[0-9]+'))) OR (TT.SAP_VERSION = T.SAP_VERSION AND (TT.MES_UPDATE_DATE > T.MES_UPDATE_DATE OR TT.MES_UPDATE_DATE = T.MES_UPDATE_DATE AND TT.MES_CREATE_DATE > T.MES_CREATE_DATE OR TT.MES_UPDATE_DATE = T.MES_UPDATE_DATE AND TT.MES_CREATE_DATE = T.MES_CREATE_DATE AND TT.ID > T.ID))))
/* 只查找本次bom数据版本更新到的记录*/ AND T.ID IN (SELECT ID FROM T_MES_BOM_INFO WHERE DATA_VERSION = #{bomDataVersion})
), PLM_TAB AS (SELECT P.*, M.CONSTRUCTION_COLUMN FROM T_PLM_CONSTRUCTION_INFO P INNER JOIN T_PLM_BOM_CONSTRUCTION_MAPPING M ON P.PARAM_CODE = M.PARAM_CODE AND M.IS_DELETE = 0 AND M.CONSTRUCTION_COLUMN IN ('CLAMPING_PRESSURE', 'CURING_TIME') AND M.SOURCE_COLUMN = 4 WHERE NOT EXISTS (SELECT 0 FROM T_PLM_CONSTRUCTION_INFO PP WHERE PP.SAP_CODE = P.SAP_CODE AND PP.PARAM_CODE = P.PARAM_CODE AND (NVL(PP.UPDATE_DATE, PP.CREATE_DATE) > NVL(P.UPDATE_DATE, P.CREATE_DATE) OR NVL(PP.UPDATE_DATE, PP.CREATE_DATE) = NVL(P.UPDATE_DATE, PP.CREATE_DATE) AND PP.ID > P.ID))) SELECT T.ID, T.PARENT_MATERIAL_CODE, REGEXP_SUBSTR(T.CHILD_CODE, '\w+') EMBRYO_CODE, P.CONSTRUCTION_COLUMN COLUMN_NAME, P.PARAM_VALUE COLUMN_VALUE, T.Child_Material_Version EMBRYO_VERSION, CASE WHEN NVL(T.STATUS, '1') = '3' THEN '1' ELSE '0' END STATUS, P.CREATE_DATE UPDATE_DATE FROM BOM_TAB T INNER JOIN PLM_TAB P ON P.SAP_CODE = T.CHILD_MATERIAL_CODE WHERE NVL(T.STATUS, '1') != '3'
/* 只查找本次Plm数据版本更新到的记录*/ AND P.ID IN (SELECT ID FROM T_MES_PLM_CONSTRUCTION_INFO WHERE DATA_VERSION = #{plmDataVersion})
UNION /* 单独查询规格描述信息 */ SELECT T.ID, T.PARENT_MATERIAL_CODE, REGEXP_SUBSTR(T.CHILD_CODE, '\w+') EMBRYO_CODE, M.CONSTRUCTION_COLUMN COLUMN_NAME, T.CHILD_CODE || '$$$' || T.PARENT_CODE COLUMN_VALUE, T.Child_Material_Version EMBRYO_VERSION, '0' STATUS, T.MES_UPDATE_DATE UPDATE_DATE FROM BOM_TAB T INNER JOIN T_PLM_BOM_CONSTRUCTION_MAPPING M ON M.CHILD_MATERIAL_NAME_CODE = T.CHILD_MATERIAL_NAME_CODE AND M.CONSTRUCTION_COLUMN IN ('SPEC_DESC') WHERE NVL(T.STATUS, '1') != '3' UNION /* 查询是否整个胎胚废止了，废止的胎胚硫化施工表也要跟着删除*/ SELECT T.ID, T.PARENT_MATERIAL_CODE, REGEXP_SUBSTR(T.CHILD_CODE, '\w+') EMBRYO_CODE, 'DEL_FLAG' COLUMN_NAME, decode(T.STATUS, '3', '1', '0') COLUMN_VALUE, /*删除字段数值，通过废止状态转换：3是废止，其他都是正常*/ T.Child_Material_Version EMBRYO_VERSION, '0' STATUS, T.MES_UPDATE_DATE UPDATE_DATE FROM BOM_TAB T
ORDER BY EMBRYO_CODE, COLUMN_VALUE, UPDATE_DATE

mapper.update:
MERGE INTO T_LH_TIRE_CONSTRUCTION_INFO a USING (
SELECT #{item.sapCode, jdbcType=VARCHAR} SAP_CODE, #{item.embryoCode, jdbcType=VARCHAR} EMBRYO_CODE, #{item.embryoVersion, jdbcType=VARCHAR} EMBRYO_VERSION, #{item.clampingPressure, jdbcType=DECIMAL} CLAMPING_PRESSURE, #{item.curingTime, jdbcType=DECIMAL} CURING_TIME, #{item.specDesc, jdbcType=VARCHAR} SPEC_DESC, #{item.delFlag, jdbcType=VARCHAR} DEL_FLAG, #{item.updateTime, jdbcType=DATE} UPDATE_TIME, c.id FROM dual LEFT JOIN T_LH_TIRE_CONSTRUCTION_INFO c ON c.SAP_CODE = #{item.sapCode, jdbcType=VARCHAR} AND c.EMBRYO_CODE = #{item.embryoCode, jdbcType=VARCHAR} AND c.EMBRYO_VERSION = #{item.embryoVersion, jdbcType=VARCHAR} AND c.DEL_FLAG = '0'
) b ON (a.id = b.id) WHEN MATCHED THEN UPDATE SET a.CLAMPING_PRESSURE = b.CLAMPING_PRESSURE, a.CURING_TIME = b.CURING_TIME, a.DEL_FLAG = CASE WHEN b.DEL_FLAG IS NOT NULL THEN b.DEL_FLAG ELSE a.DEL_FLAG END, a.SPEC_DESC = CASE WHEN b.SPEC_DESC IS NOT NULL THEN b.SPEC_DESC ELSE a.SPEC_DESC END, a.UPDATE_TIME = b.UPDATE_TIME WHEN NOT MATCHED THEN INSERT (a.ID, a.SAP_CODE, a.EMBRYO_CODE, a.EMBRYO_VERSION, a.SPEC_DESC, a.CLAMPING_PRESSURE, a.CURING_TIME, a.DEL_FLAG, a.CREATE_TIME) VALUES (get_sequence_nextval('SEQ_CONSTRUCTION_INFO'), b.SAP_CODE, b.EMBRYO_CODE, b.EMBRYO_VERSION, b.SPEC_DESC, b.CLAMPING_PRESSURE, b.CURING_TIME, b.DEL_FLAG, b.UPDATE_TIME)

UPDATE T_PRODUCT_CONSTRUCTION_INFO T SET T.DEL_FLAG = '1', T.Update_Time = now() WHERE T.EMBRYO_CODE IN (
SELECT #{embryoCode} EMBRYOCODE FROM DUAL
) AND NOT EXISTS (SELECT 0 FROM T_CONSTRUCTION_VERSION_INFO TT WHERE TT.EMBRYO_CODE = T.EMBRYO_CODE AND TT.EMBRYO_VERSION = T.EMBRYO_VERSION AND TT.DEL_FLAG = '0') AND T.DEL_FLAG = '0'
